export const sum=a=>a.reduce((s,n)=>s+n,0);
export const money=cents=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',maximumFractionDigits:2,minimumFractionDigits:cents%100?2:0}).format(cents/100);
export const clone=x=>structuredClone(x);
export function unitCost(s,i){const p=s.products[i];if(!p||!p.batch)return 0;const batchCost=sum(p.recipe.map((qty,j)=>{const ing=s.ingredients[j];return ing&&ing.pack?qty*(ing.cost/ing.pack):0;}));return Math.round(batchCost/p.batch);}
export function seed(){return {version:2,view:'today',business:{name:'Mila’s Neighborhood Bakery',type:'Bakery',owner:'Aling Mila'},budget:30000,capacity:240,orders:[12,0,0],fallback:[36,24,12],useHistory:true,override:'none',
products:[{name:'Pandesal',note:'The neighborhood favorite',unit:'piece',price:800,batch:12,minutes:20,recipe:[400,40,30,1,5]},{name:'Spanish bread',note:'Soft, buttery, familiar',unit:'piece',price:1500,batch:12,minutes:25,recipe:[450,100,80,2,5]},{name:'Cheese rolls',note:'A little afternoon treat',unit:'piece',price:1800,batch:12,minutes:25,recipe:[420,60,60,1,5]}],
ingredients:[{name:'Flour',unit:'g',stock:1600,pack:500,cost:4000},{name:'Sugar',unit:'g',stock:200,pack:250,cost:2500},{name:'Butter',unit:'g',stock:150,pack:100,cost:4000},{name:'Eggs',unit:'pcs',stock:5,pack:6,cost:4800},{name:'Yeast',unit:'g',stock:30,pack:25,cost:500}],
history:[{date:'Sep 4',day:'Friday',walkin:[34,22,10],preorders:[12,0,0],early:false},{date:'Sep 11',day:'Friday',walkin:[36,24,12],preorders:[12,0,0],early:false},{date:'Sep 18',day:'Friday',walkin:[38,26,14],preorders:[12,0,0],early:false}],
today:{date:'2026-09-24',day:'Thursday',prepared:[60,36,24],sold:[42,24,15],discarded:[0,0,0],preorderSold:[12,0,0],early:[false,false,false]},draft:null,approval:null,midday:null,outcome:null};}
export function demand(s){const h=s.useHistory?s.history.filter(d=>d.day==='Friday'):[];return {walkin:s.products.map((_,i)=>h.length?Math.round(sum(h.map(d=>d.walkin[i]||0))/h.length):(s.fallback[i]||0)),source:h.length?`${h.length} comparable Fridays`:'Owner baseline · no comparable history',limited:h.length<3,early:h.some(d=>d.early)};}
export const ceilBatch=(n,b)=>Math.ceil(n/b)*b;
export function cost(s,qty){const used=s.ingredients.map((_,j)=>sum(s.products.map((p,i)=>(qty[i]||0)/p.batch*(p.recipe[j]||0))));const lines=s.ingredients.map((g,j)=>{const packs=Math.ceil(Math.max(0,used[j]-g.stock)/g.pack);return {...g,used:used[j],packs,buy:packs*g.pack,cash:packs*g.cost,consumed:Math.round(used[j]*g.cost/g.pack)};});const perProduct=s.products.map((p,i)=>{const q=qty[i]||0,u=unitCost(s,i),rev=q*p.price,cons=q*u;return {name:p.name,qty:q,unitCost:u,revenue:rev,consumed:cons,contribution:rev-cons};});return {lines,perProduct,cash:sum(lines.map(g=>g.cash)),consumed:sum(lines.map(g=>g.consumed)),minutes:sum(s.products.map((p,i)=>(qty[i]||0)/p.batch*p.minutes))};}
export function validatePlan(s,total,initial){const errors=[];for(let i=0;i<s.products.length;i++){const p=s.products[i];if(!Number.isSafeInteger(total[i])||total[i]<0||total[i]%p.batch||!Number.isSafeInteger(initial[i])||initial[i]<0||initial[i]%p.batch)errors.push(`${p.name}: use whole batches of ${p.batch}.`);if(initial[i]>total[i])errors.push(`${p.name}: initial quantity exceeds total.`);if(initial[i]<(s.orders[i]||0))errors.push(`${p.name}: reserve all ${s.orders[i]||0} confirmed orders in the initial preparation.`);}const c=cost(s,total);if(c.cash>s.budget)errors.push(`Purchases need ${money(c.cash-s.budget)} more than your budget.`);if(c.minutes>s.capacity)errors.push(`Preparation needs ${c.minutes-s.capacity} more minutes than available.`);return {errors,...c};}
export function plan(s){const d=demand(s),minimum=s.products.map((p,i)=>ceilBatch(s.orders[i]||0,p.batch));const target=s.products.map((p,i)=>ceilBatch(d.walkin[i]+(s.orders[i]||0),p.batch));const initialTarget=s.products.map((p,i)=>Math.min(target[i],Math.max(minimum[i],ceilBatch((s.orders[i]||0)+d.walkin[i]*0.5,p.batch))));let qty=[...minimum];const fits=q=>{const c=cost(s,q);return c.cash<=s.budget&&c.minutes<=s.capacity;};const allocate=goals=>{let changed=true;while(changed){changed=false;for(let i=0;i<s.products.length;i++){if(qty[i]>=goals[i])continue;const next=[...qty];next[i]+=s.products[i].batch;if(fits(next)){qty=next;changed=true;}}}};if(fits(qty)){allocate(initialTarget);const initial=[...qty];allocate(target);return {...d,target,total:qty,initial,conditional:qty.map((n,i)=>n-initial[i]),...validatePlan(s,qty,initial)};}return {...d,target,total:qty,initial:qty,conditional:s.products.map(()=>0),...validatePlan(s,qty,qty)};}
export function selectedPlan(s){const p=plan(s);if(s.approval){const a=s.approval;return {...p,walkin:a.walkin,target:a.target,total:a.total,initial:a.initial,conditional:a.conditional,...a.cost,errors:[]};}if(!s.draft)return p;const {total,initial}=s.draft;return {...p,total,initial,conditional:total.map((n,i)=>n-initial[i]),...validatePlan(s,total,initial)};}
export function approve(s,now=Date.now()){const p=selectedPlan(s);if(p.errors.length)throw Error(p.errors.join(' '));return {at:now,target:[...p.target],total:[...p.total],initial:[...p.initial],conditional:[...p.conditional],orders:[...s.orders],walkin:[...p.walkin],cost:cost(s,p.total),products:clone(s.products),ingredients:clone(s.ingredients),business:clone(s.business),budget:s.budget,capacity:s.capacity,override:s.override||'none'};}
export function validateRecord(r,products,{preorders=false}={}){const errors=[];for(let i=0;i<products.length;i++){const fields=['prepared','sold','discarded',...(preorders?['preorderSold']:[])];if(fields.some(f=>!Number.isSafeInteger(r[f]?.[i])||r[f][i]<0))errors.push(`${products[i].name}: enter nonnegative whole numbers.`);if(r.prepared[i]%products[i].batch)errors.push(`${products[i].name}: prepared quantity must use batches of ${products[i].batch}.`);if(r.sold[i]+r.discarded[i]>r.prepared[i])errors.push(`${products[i].name}: sold and discarded cannot exceed prepared.`);if(preorders&&r.preorderSold[i]>r.sold[i])errors.push(`${products[i].name}: collected preorders cannot exceed total sold.`);}return errors;}
export function checkMidday(a,m,now=Date.now()){const zeros=()=>a?.products?.map(()=>0)||[];if(!a)return {status:'blocked',message:'Approve a plan before the midday check.',batches:[]};if(!m||now-m.at>60*60*1000||m.at>now+60000)return {status:'stale',message:'Update your counts. The last check is missing or over 60 minutes old.',batches:zeros()};const errors=[];for(let i=0;i<a.products.length;i++){if([m.sold[i],m.remaining[i]].some(n=>!Number.isSafeInteger(n)||n<0)||m.sold[i]+m.remaining[i]!==a.initial[i]-a.orders[i])errors.push(`${a.products[i].name}: walk-in sales + remaining must equal ${a.initial[i]-a.orders[i]} unreserved units.`);}if(errors.length)return {status:'blocked',message:errors.join(' '),batches:zeros()};const batches=a.products.map((p,i)=>{const afternoonEstimate=m.sold[i];return afternoonEstimate>m.remaining[i]&&a.conditional[i]>=p.batch?p.batch:0;});const ready=sum(batches)>0;return {status:ready?'prepare':'delay',message:ready?'Prepare one additional batch where the remaining stock is below the afternoon estimate.':'Sales are slower. Your remaining units cover an afternoon at the same pace. Delay the additional batches.',batches};}
export function outcome(s,r){const products=s.approval?.products||s.products;const errors=validateRecord(r,products,{preorders:true});if(s.approval){for(let i=0;i<products.length;i++){if(r.preorderSold[i]>s.approval.orders[i])errors.push(`${products[i].name}: collected preorders exceed confirmed orders.`);if(r.prepared[i]<s.approval.initial[i])errors.push(`${products[i].name}: cannot record fewer than the initial preparation.`);if(r.prepared[i]>s.approval.total[i])errors.push(`${products[i].name}: exceeds the approved maximum; revise your plan first.`);}}const source=s.approval?{...s,products,ingredients:s.approval.ingredients}:s;const consumed=cost(source,r.prepared).consumed;const revenue=sum(products.map((p,i)=>p.price*r.sold[i]));return {errors,revenue,consumed,contribution:revenue-consumed,unsold:sum(r.prepared)-sum(r.sold)-sum(r.discarded),discarded:sum(r.discarded)};}
